// EMA状态结构体（紧凑存储，减少内存占用）
typedef struct {
    float alpha;           // 平滑系数α（0 < α ≤ 1）
    float one_minus_alpha; // 预计算 1-α，加速更新
    float ema;             // 当前EMA值
    uint8_t initialized;      // 是否已初始化（首次输入时标记）
} EMA;


/**
 * @brief 初始化EMA（直接设置α）
 * @param ema: EMA结构体指针
 * @param alpha: 平滑系数（0 < alpha ≤ 1），超出范围自动修正为0.5
 */
void ema_init(EMA* ema, float alpha) {
    if (ema == NULL) return; // 避免空指针崩溃

    // 修正α范围（确保0 < α ≤ 1）
    if (alpha <= 0.0f || alpha > 1.0f) {
        alpha = 0.5f; // 默认α=0.5
    }

    ema->alpha = alpha;
    ema->one_minus_alpha = 1.0f - alpha; // 预计算1-α，加速更新
    ema->ema = 0.0f;
    ema->initialized = 0; // 未初始化状态
}

/**
 * @brief 更新EMA并返回当前值
 * @param ema: EMA结构体指针
 * @param x: 当前输入值（需为数值型，如传感器读数）
 * @return 更新后的EMA值
 */
float ema_update(EMA* ema, float x) {
    if (ema == NULL) return 0.0f; // 空指针返回0

    // 首次输入：用x初始化EMA
    if (!ema->initialized) {
        ema->ema = x;
        ema->initialized = 1;
        return ema->ema;
    }
    // 递推公式：EMA = α·x + (1-α)·EMA_prev
    ema->ema = ema->alpha * x + ema->one_minus_alpha * ema->ema;
    return ema->ema;
}


