static void _SuctionCase_Init(SuctionCase *_this,void(*out)(int16_t),float (*_getsensor)())
{
    _this->outctl = out;
    _this->_getpressure = _getsensor;
    _this->_enable = 0;
    PID_Constructor_Inc(&_this->_pid);
    _this->_pid.SetIntegralPrm(&_this->_pid,2,-60);
    _this->_pid.SetCtrlPrm(&_this->_pid,-0.8,-0.005,-10);
}

static void _SuctionCase_Handler(SuctionCase *_this)
{
    if (_this->_enable)
    {
        _this->_error = _this->_getpressure() - _this->_targetVaccum;
        int16_t _out = _this->_pid.PID(&_this->_pid, _this->_error);
        Suction_inst.Wdata->_ctlValue = _out;
        _this->outctl(_out);
    }
}

static void _SuctionCase_Ctl(SuctionCase *_this,uint8_t _en,uint16_t _target)
{
    _this->_enable = _en;
    _this->_targetVaccum = _target;
}

static uint32_t _Suction_Get_InputValue(uint32_t _min, uint32_t _max,uint32_t _percent)
{
    if (_min >= _max)
    {
        _min = _max;
    }
    return (_percent==0?0:(_percent * (_max - _min) / 100) + _min);
}


