int  Suction_Task_Init()
{
    Suction_ctor();
    _clenCassetteTimer = rt_timer_create("clean", _Suction_Task_CleanTimeout,RT_NULL,34*1000,RT_TIMER_FLAG_ONE_SHOT);
    Normal_Task_RegisterFun(Suction_Task_Cmd);
    Pedal_Task_RegisterFun(Suction_Task_Pedal_Deal);
    QActive_setAttr(AO_Suction,THREAD_NAME_ATTR,"suction_qm");
    QACTIVE_START(AO_Suction,QPC_SUCTION_PRO,Suction_queueSto,Q_DIM(Suction_queueSto),Suction_task_stack,SUCTION_TASK_SIZE,NULL);
}
INIT_APP_EXPORT(Suction_Task_Init);

//$define${AOs::Suction_ctor} vvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv

//${AOs::Suction_ctor} .......................................................
uint32_t Suction_ctor(void) {
    Suction_inst.Wcof = &ramcof._suctioncof;
    Suction_inst.Wdata = &ramdata._suctionData;
    _suctioncof = Suction_inst.Wcof;

    _MotorPump.channel = 0;
    bsp_prsureSen_Init(&_MotorPump,_SuctionMotorSensor_Read); //

    // 1.从Flash中加载参数
    struct Flash_Motor *_motor = ( struct Flash_Motor *)Flash_Task_Read("motor");
    if (_motor->_unuse == FLASH_PRAMS_VERIFY)   //Flash中有配置参数
    {
        bsp_prsureSen_SetCalib(&_MotorPump,_motor->_pumpMotor); //使用Flash中的配置参数
    }
    else
        bsp_prsureSen_SetCalib(&_MotorPump,Pumpcali);
    
    Data_Task_RegisterSensor(&_MotorPump,&Suction_inst.Wdata->_motorctlstep,&Suction_inst.Wdata->_ctlflowcc);
    _VaccumSensor.channel =EXTERN_VACCUM_PRESSURE_ADC_CH;
    bsp_prsureSen_Init(&_VaccumSensor,_VaccumPressureSensor_Read); //
    bsp_prsureSen_SetCalib(&_VaccumSensor,Vaccumcali);

    Data_Task_RegisterSensor(&_VaccumSensor,&Suction_inst.Wdata->_vaccumRawdata,&Suction_inst.Wdata->_vaccumpressure);

    _SuctionCase_Init(&_suctioncase,bsp_suction_SourceCtl,_Suction_Task_GetPressure);

    Suction  *me = &Suction_inst;

    me->_flowema = rt_calloc(1, sizeof(EMA));
    ema_init(me->_flowema, 0.5);


    QActive_ctor(&me->super, Q_STATE_CAST(&Suction_initial));
    QTimeEvt_ctorX(&me->_timEvt, &me->super, TIMEOUT_SIG, 0U);
}
//$enddef${AOs::Suction_ctor} ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
