//${AOs::Suction} ............................................................
Suction Suction_inst;

//${AOs::Suction::SM} ........................................................
static QState Suction_initial(Suction * const me, void const * const par) {
    //${AOs::Suction::SM::initial}
    QActive_subscribe(&me->super, CASSETTEINDOWN_SIG);
    QActive_subscribe(&me->super, CASSETTERELEASE_SIG);
    
    return Q_TRAN(&Suction_waitCassetteIn);
}

//${AOs::Suction::SM::waitCassetteIn} ........................................
static QState Suction_waitCassetteIn(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::waitCassetteIn}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SUCTION_STATE_WAIT;
//            bsp_suction_SourceCtl(60);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::waitCassetteIn}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SUCTION_STATE_WAIT;
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::waitCassetteIn::CASSETTEINDOWN}
        case CASSETTEINDOWN_SIG: {
            status_ = Q_TRAN(&Suction_active);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${AOs::Suction::SM::active} ................................................
static QState Suction_active(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::active::initial}
        case Q_INIT_SIG: {
            status_ = Q_TRAN(&Suction_Suction_Idel);
            break;
        }
        //${AOs::Suction::SM::active::CASSETTERELEASE}
        case CASSETTERELEASE_SIG: {
            status_ = Q_TRAN(&Suction_waitCassetteIn);
            break;
        }
        //${AOs::Suction::SM::active::SUCTION_STOP}
        case SUCTION_STOP_SIG: {
            status_ = Q_TRAN(&Suction_Suction_Idel);
            break;
        }
        //${AOs::Suction::SM::active::SUCTION_ENABLE}
        case SUCTION_ENABLE_SIG: {
            status_ = Q_TRAN(&Suction_Suction_Run);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${AOs::Suction::SM::active::Suction_Idel} ..................................
static QState Suction_Suction_Idel(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::active::Suction_Idel}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SUCTION_STATE_IDEL;
            bsp_suction_SourceCtl(0);
            if(me->Wdata->_prstate >=SUCTION_STATE_RUN && Suction_inst.Wdata->_ctlValue>0)
            {
                ErigeEvt *pe;
                pe = Q_NEW(ErigeEvt,DRAIN_ENABLE_SIG);
                QACTIVE_POST(AO_Reflux,&pe->super,NULL);
            }
            me->Wdata->_percentofPedal = 0;
            me->Wdata->_ctlValue = 0;
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Idel}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SUCTION_STATE_IDEL;
            status_ = Q_HANDLED();
            break;
        }
        default: {
            status_ = Q_SUPER(&Suction_active);
            break;
        }
    }
    return status_;
}

//${AOs::Suction::SM::active::Suction_Run} ...................................
static QState Suction_Suction_Run(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::active::Suction_Run}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SUCTION_STATE_RUN;
            //QTimeEvt_armX(&me->_timEvt, 10, 10U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run}
        case Q_EXIT_SIG: {
			//QTimeEvt_disarm(&me->_timEvt);    //关闭定时器
            me->Wdata->_prstate = SUCTION_STATE_RUN;
            bsp_suction_SourceCtl(0);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::TIMEOUT}
        // case TIMEOUT_SIG: {
        //     bsp_suction_SourceCtl(me->Wdata->_ctlValue);
        //     status_ = Q_HANDLED();
        //     break;
        // }
        case Q_INIT_SIG: {
            status_ = Q_TRAN(&Suction_Suction_NoBlock);
            break;
        }
        default: {
            status_ = Q_SUPER(&Suction_active);
            break;
        }
    }
    return status_;
}
static QState Suction_Suction_NoBlock(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::active::Suction_Run::Suction_NoBlock}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SUCTION_STATE_RUNNOBLOCK;
            me->_timcnt = 0;    //计数值清0
            QTimeEvt_armX(&me->_timEvt, 10, 10U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::Suction_NoBlock}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SUCTION_STATE_RUNNOBLOCK;
            QTimeEvt_disarm(&me->_timEvt);    //关闭定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::Suction_NoBlock::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;    //计数值加1
            //${AOs::Suction::SM::active::Suction_Run::Suction_NoBlock::TIMEOUT::[enblock]}
            if (me->Wcof->_enBlockmode == 1 && (-(me->Wdata->_vaccumpressure) >me->Wcof->_vaccumCof._blockvalue)) {
                status_ = Q_TRAN(&Suction_Suction_Blocking);
            }
            //${AOs::Suction::SM::active::Suction_Run::Suction_NoBlock::TIMEOUT::[else]}
            else {

                me->Wdata->_inputCtlValue  = _Suction_Get_InputValue(me->Wcof->_flowCof._minflow,me->Wcof->_flowCof._maxflow,me->Wdata->_percentofPedal);
                me->Wdata->_vaccumLimit  = _Suction_Get_InputValue(me->Wcof->_vaccumCof._minvalue,me->Wcof->_vaccumCof._maxvalue,me->Wdata->_percentofPedal);
                Suction_Task_Handler(me->Wdata->_inputCtlValue,me->Wcof->_flowCof.pumpRamp._unoccluded,me->Wdata->_vaccumLimit);

                if(me->Wcof->_vaccumCof._case._enCaseMode)  //使能case模式
                {
                    if (-(me->Wdata->_vaccumpressure)>=me->Wcof->_vaccumCof._case._upVaccum)
                    {
                        if((me->_timcnt * 10) >me->Wcof->_vaccumCof._case._vaccumDurationTime)
                        {
                            status_ = Q_TRAN(&Suction_Suction_CASE);
                        }
                        else
                            status_ = Q_HANDLED();
                    }
                    else
                    {
                        me->_timcnt = 0;
                        status_ = Q_HANDLED();
                    }
                }
                else
                    status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Suction_Suction_Run);
            break;
        }
    }
    return status_;
}

//${AOs::Suction::SM::active::Suction_Run::Suction_Blocking} .................
static QState Suction_Suction_Blocking(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::active::Suction_Run::Suction_Blocking}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SUCTION_STATE_RUNBLOCKING;
            me->_timcnt = 0;    //计数值清0
            QTimeEvt_armX(&me->_timEvt, 10, 10U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::Suction_Blocking}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SUCTION_STATE_RUNBLOCKING;
            QTimeEvt_disarm(&me->_timEvt);    //关闭定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::Suction_Blocking::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;    //计数值加1
            //${AOs::Suction::SM::active::Suction_Run::Suction_Blocking::TIMEOUT::[Noblock]}
            if (-(me->Wdata->_vaccumpressure) <=me->Wcof->_vaccumCof._blockvalue) {
                status_ = Q_TRAN(&Suction_Suction_NoBlock);
            }
            //${AOs::Suction::SM::active::Suction_Run::Suction_Blocking::TIMEOUT::[else]}
            else {
                // me->Wdata->_inputCtlValue  = me->Wcof->_flowCof._blockflow;
                uint32_t _blockminflow = (me->Wcof->_flowCof._minflow==me->Wcof->_flowCof._maxflow?me->Wcof->_flowCof._blockflow:(me->Wcof->_flowCof._blockflow<me->Wcof->_flowCof._minflow?0:me->Wcof->_flowCof._minflow));
                uint32_t _blockmaxflow = me->Wcof->_flowCof._blockflow;
                me->Wdata->_inputCtlValue  = _Suction_Get_InputValue(_blockminflow,_blockmaxflow,me->Wdata->_percentofPedal);
                me->Wdata->_vaccumLimit  = _Suction_Get_InputValue(me->Wcof->_vaccumCof._minvalue,me->Wcof->_vaccumCof._maxvalue,me->Wdata->_percentofPedal);
                Suction_Task_Handler(me->Wdata->_inputCtlValue,me->Wcof->_flowCof.pumpRamp._occluded,me->Wdata->_vaccumLimit);

                if(me->Wcof->_vaccumCof._case._enCaseMode)  //使能case模式
                {
                    if (-(me->Wdata->_vaccumpressure)>=me->Wcof->_vaccumCof._case._upVaccum)
                    {
                        if((me->_timcnt * 10) >me->Wcof->_vaccumCof._case._vaccumDurationTime)
                        {
                            status_ = Q_TRAN(&Suction_Suction_CASE);
                        }
                        else
                            status_ = Q_HANDLED();
                    }
                    else
                    {
                        
                        me->_timcnt = 0;
                        status_ = Q_HANDLED();
                    }
                }
                // status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Suction_Suction_Run);
            break;
        }
    }
    return status_;
}
//$enddef${AOs::Suction} ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
static QState Suction_Suction_CASE(Suction * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Suction::SM::active::Suction_Run::Suction_CASE}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SUCTION_STATE_CASE;
            // bsp_suction_SourceCtl(-me->Wdata->_ctlValue);
            // bsp_suction_SourceCtl(-me->Wdata->_inputCtlValue);
            _SuctionCase_Ctl(&_suctioncase,1,me->Wcof->_vaccumCof._case._targetVaccum);
            QTimeEvt_armX(&me->_timEvt, 5, 5U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::Suction_CASE}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SUCTION_STATE_CASE;
            QTimeEvt_disarm(&me->_timEvt);    //关闭定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Suction::SM::active::Suction_Run::Suction_CASE::TIMEOUT}
        case TIMEOUT_SIG: {
            // uint32_t _decvaccum = (me->Wcof->_vaccumCof._case._upVaccum -  me->Wcof->_vaccumCof._case._targetVaccum)*0.2+me->Wcof->_vaccumCof._case._targetVaccum;
            if(-(me->Wdata->_vaccumpressure)<=(me->Wcof->_vaccumCof._case._targetVaccum))
            {
                Suction_inst.Wdata->_ctlValue = 0;
                bsp_suction_SourceCtl(0);    //停止
                _SuctionCase_Ctl(&_suctioncase,0,me->Wcof->_vaccumCof._case._targetVaccum);
            }
            // else if(-(me->Wdata->_vaccumpressure)<_decvaccum)
            // {
            //     bsp_suction_SourceCtl(-1); 
            // }
            else
            {
                _SuctionCase_Handler(&_suctioncase);
            }
            //${AOs::Suction::SM::active::Suction_Run::Suction_CASE::TIMEOUT::[change]}
            if (-(me->Wdata->_vaccumpressure)<(me->Wcof->_vaccumCof._case._downVaccum)) {
                //${AOs::Suction::SM::active::Suction_Run::Suction_CASE::TIMEOUT::[change]::[me->Wdata->_prstate==SUCTION_ST~}
                if (me->Wdata->_prstate == SUCTION_STATE_RUNBLOCKING) {
                    status_ = Q_TRAN(&Suction_Suction_Blocking);
                }
                //${AOs::Suction::SM::active::Suction_Run::Suction_CASE::TIMEOUT::[change]::[me->Wdata->_prstate==SUCTION_ST~}
                else if (me->Wdata->_prstate == SUCTION_STATE_RUNNOBLOCK) {
                    status_ = Q_TRAN(&Suction_Suction_NoBlock);
                }
                else {
                    status_ = Q_HANDLED();
                }
            }
            else {
                status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Suction_Suction_Run);
            break;
        }
    }
    return status_;
}